import { queryOptions, useQuery } from '@tanstack/react-query';

import { api } from '@/lib/api-client';
import { QueryConfig } from '@/lib/react-query';
import { User } from '@/types/api';

export const getUsers = (params?: { role?: string; search?: string }): Promise<{ data: User[] }> => {
  return api.get(`/users`, { params });
};

export const getUsersQueryOptions = (params?: { role?: string; search?: string }) => {
  return queryOptions({
    queryKey: ['users', params],
    queryFn: () => getUsers(params),
  });
};

type UseUsersOptions = {
  queryConfig?: QueryConfig<typeof getUsersQueryOptions>;
  params?: { role?: string; search?: string };
};

export const useUsers = ({ queryConfig, params }: UseUsersOptions = {}) => {
  return useQuery({
    ...getUsersQueryOptions(params),
    ...queryConfig,
  });
};

import { User } from '@/types/api';

export const downloadUsersCsv = (users: User[]) => {
  const header = 'Name,Email,Role,Joined\n';
  const rows = users
    .map((user) => {
      const name = `"${user.firstName} ${user.lastName}"`;
      const email = `"${user.email}"`;
      const role = user.role;
      const joined = `"${new Date(user.createdAt).toLocaleDateString('en-GB', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
      })}"`;
      return `${name},${email},${role},${joined}`;
    })
    .join('\n');

  const csvContent = `${header}${rows}`;
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'users.csv';
  link.click();
  URL.revokeObjectURL(url);
};

